// Decide qué hace verificacion-completitud con lo que devolvió notificacion-multicanal para el aviso de
// documentos faltantes (HU0017-2.0). Sigue ADR-07 «Fallos de los avisos de la visita» y ADR-22: la clasificación de D7,
// sin rebote ni transición (P-j).
// Entrada: un ítem por aviso, emparejado con su aviso de la salida «incompleto» de «Según la verificación» por el pairedItem
// que pone Execute Workflow (el subflujo corre una vez por ítem); si falta, por la posición. Es el resultado del
// subflujo, { id_expediente, correo: { estado_envio, id_notificacion }, whatsapp }, o, si falló, { error: "<mensaje>" }
// (Execute Workflow con onError continueRegularOutput, C9).
//   enviado   <- correo.estado_envio = enviado: el subflujo ya cerró la fila                    -> termina
//   fallido   <- correo.estado_envio = fallido: rechazo permanente del destinatario; con la fila reservada el subflujo
//                no la cierra                      (motivo rechazo_destinatario) -> PATCH fallido y termina sin error
//             <- error «notificacion-multicanal: entrada inválida…» (400): un defecto, la entrada la arma la API
//                                                  (motivo entrada_invalida)     -> PATCH fallido y Stop and Error
//   pendiente <- correo.estado_envio = pendiente (error técnico de SMTP, o un 5xx que no es rechazo permanente), un 502,
//                un 500 o cualquier otro error: resultado desconocido (R22), nunca se marca fallido
//                                                  -> sin PATCH y Stop and Error; el barrido lo retoma a los 10 min
//                                                     con un intento nuevo (una fila por intento, ADR-07)
// Lo que no se reconoce cae en pendiente.
// La salida lleva solo la acción, el motivo y los ids del expediente y la notificación. Nunca el asunto ni el cuerpo del
// aviso (trae la lista de faltantes), ni el mensaje del error del subflujo (C11).
const ENTRADA_INVALIDA = 'notificacion-multicanal: entrada inválida';
const reservas = $('Según la verificación').all(1);

const clasificar = (resultado) => {
  if (resultado.error !== undefined) {
    const mensaje = typeof resultado.error === 'string' ? resultado.error : String(resultado.error?.message ?? '');
    return mensaje.startsWith(ENTRADA_INVALIDA)
      ? { accion: 'fallido', motivo: 'entrada_invalida' }
      : { accion: 'pendiente', motivo: 'notificacion_no_disponible' };
  }
  switch (resultado.correo?.estado_envio) {
    case 'enviado':
      return { accion: 'enviado', motivo: 'enviado' };
    case 'fallido':
      return { accion: 'fallido', motivo: 'rechazo_destinatario' };
    case 'pendiente':
      return { accion: 'pendiente', motivo: 'smtp_pendiente' };
    default:
      return { accion: 'pendiente', motivo: 'resultado_desconocido' };
  }
};

return $input.all().map((item, indice) => {
  const reserva = reservas[item.pairedItem?.item ?? indice]?.json?.body ?? {};
  return {
    json: {
      ...clasificar(item.json ?? {}),
      id_expediente: reserva.id_expediente ?? null,
      id_notificacion: reserva.id_notificacion ?? null,
    },
    pairedItem: { item: indice },
  };
});

// Valida el evento que envía la API después del COMMIT de una observación (HU0008-2.0, HU0011-2.0 y HU0024-2.0), según
// ADR-16: el cuerpo es exactamente { id_expediente, id_notificacion } con enteros de 1 a 2147483647. Cualquier otro campo
// lo invalida: el contrato lleva solo identificadores (C10, C11). La salida lleva solo { valido, id_expediente, id_notificacion }.
const esObjeto = (valor) => valor !== null && typeof valor === 'object' && !Array.isArray(valor);
const entero = (n) => Number.isSafeInteger(n) && n > 0 && n <= 2147483647;

return $input.all().map((item, indice) => {
  const cuerpo = esObjeto(item.json?.body) ? item.json.body : null;
  const claves = cuerpo ? Object.keys(cuerpo).sort() : [];
  const valido = claves.length === 2 && claves[0] === 'id_expediente' && claves[1] === 'id_notificacion' && entero(cuerpo.id_expediente) && entero(cuerpo.id_notificacion);
  return {
    json: { valido, id_expediente: valido ? cuerpo.id_expediente : null, id_notificacion: valido ? cuerpo.id_notificacion : null },
    pairedItem: { item: indice },
  };
});

// Barrido de la rama validación de verificacion-completitud (ADR-16, C27; HU0008-2.0, HU0011-2.0 y HU0024-2.0): un ítem por
// cada expediente de GET /internal/observaciones/pendientes (observaciones cuyo aviso nunca se reservó o cuyo último intento
// lleva más de 10 min pendiente). Sin id_notificacion: la API retoma con una fila nueva o cierra por tope (ADR-07). Si no hay
// pendientes no sale ningún ítem y la ejecución termina aquí. Solo lleva identificadores.
const salida = [];
$input.all().forEach((item, indice) => {
  const expedientes = Array.isArray(item.json?.expedientes) ? item.json.expedientes : [];
  for (const e of expedientes) {
    if (Number.isSafeInteger(e?.id_expediente) && e.id_expediente > 0 && e.id_expediente <= 2147483647) {
      salida.push({ json: { id_expediente: e.id_expediente, id_notificacion: null }, pairedItem: { item: indice } });
    }
  }
});
return salida;

// Decide qué hace la rama validación de verificacion-completitud con lo que devolvió notificacion-multicanal para el aviso
// de observaciones (HU0008-2.0, HU0011-2.0 y HU0024-2.0). Sigue ADR-07 «Fallos de los avisos» (clasificación de D7, sin
// rebote ni transición).
// Entrada: un ítem por aviso, emparejado con su reserva (salida «reservado» de «Según la reserva») por el pairedItem que pone
// Execute Workflow; si falta, por la posición. Es el resultado del subflujo, { id_expediente, correo: { estado_envio,
// id_notificacion }, whatsapp }, o, si falló, { error: "<mensaje>" } (Execute Workflow con onError continueRegularOutput, C9).
//   enviado   <- correo.estado_envio = enviado: el subflujo ya cerró la fila                    -> termina
//   fallido   <- correo.estado_envio = fallido: rechazo permanente del destinatario (motivo rechazo_destinatario)
//                                                                                              -> PATCH fallido, sin error
//             <- error «notificacion-multicanal: entrada inválida…» (400): un defecto (motivo entrada_invalida)
//                                                                                              -> PATCH fallido y registro del fallo
//   pendiente <- correo.estado_envio = pendiente, un 502, un 500 o cualquier otro error: resultado desconocido (R22), nunca
//                se marca fallido -> sin PATCH y registro del fallo; el barrido lo retoma a los 10 min con un intento nuevo
// Lo que no se reconoce cae en pendiente.
// La salida lleva solo la acción, el motivo y los ids del expediente y la notificación. Nunca el asunto ni el cuerpo del
// aviso (llevan el motivo de la observación), ni el mensaje del error del subflujo (C11).
const ENTRADA_INVALIDA = 'notificacion-multicanal: entrada inválida';
const reservas = $('Según la reserva').all(0);

const clasificar = (resultado) => {
  if (resultado.error !== undefined) {
    const mensaje = typeof resultado.error === 'string' ? resultado.error : String(resultado.error?.message ?? '');
    return mensaje.startsWith(ENTRADA_INVALIDA)
      ? { accion: 'fallido', motivo: 'entrada_invalida' }
      : { accion: 'pendiente', motivo: 'notificacion_no_disponible' };
  }
  switch (resultado.correo?.estado_envio) {
    case 'enviado':
      return { accion: 'enviado', motivo: 'enviado' };
    case 'fallido':
      return { accion: 'fallido', motivo: 'rechazo_destinatario' };
    case 'pendiente':
      return { accion: 'pendiente', motivo: 'smtp_pendiente' };
    default:
      return { accion: 'pendiente', motivo: 'resultado_desconocido' };
  }
};

return $input.all().map((item, indice) => {
  const reserva = reservas[item.pairedItem?.item ?? indice]?.json?.body ?? {};
  return {
    json: {
      ...clasificar(item.json ?? {}),
      id_expediente: reserva.id_expediente ?? null,
      id_notificacion: reserva.id_notificacion ?? null,
    },
    pairedItem: { item: indice },
  };
});

// Rama de error de «Reservar aviso de observación» en la rama validación de verificacion-completitud (HU0008-2.0, HU0011-2.0 y HU0024-2.0, C2 y
// C41-4): un expediente que falla no frena a los demás del barrido, y este nodo prepara el registro del fallo. Emite solo los
// identificadores que admite POST /internal/errores-flujo: el flujo, el nodo y el id de esta ejecución. NO lee el ítem de
// entrada: trae el mensaje del error o el asunto y el cuerpo del aviso (llevan el motivo de la observación, C11).
// Un ítem de salida por cada expediente que falló.
const id = String($execution?.id ?? '');
const id_ejecucion = /^[0-9A-Za-z-]{1,40}$/.test(id) ? id : 'sin-id';

return $input.all().map((_item, indice) => ({
  json: { flujo: 'verificacion-completitud', nodo: 'Reservar aviso de observación', id_ejecucion },
  pairedItem: { item: indice },
}));

// Rama de error de «Enviar observación» en la rama validación de verificacion-completitud (HU0008-2.0, HU0011-2.0 y HU0024-2.0, C2 y
// C41-4): un expediente que falla no frena a los demás del barrido, y este nodo prepara el registro del fallo. Emite solo los
// identificadores que admite POST /internal/errores-flujo: el flujo, el nodo y el id de esta ejecución. NO lee el ítem de
// entrada: trae el mensaje del error o el asunto y el cuerpo del aviso (llevan el motivo de la observación, C11).
// Un ítem de salida por cada expediente que falló.
const id = String($execution?.id ?? '');
const id_ejecucion = /^[0-9A-Za-z-]{1,40}$/.test(id) ? id : 'sin-id';

return $input.all().map((_item, indice) => ({
  json: { flujo: 'verificacion-completitud', nodo: 'Enviar observación', id_ejecucion },
  pairedItem: { item: indice },
}));
